---刷新卡牌信息
---@param cardDojo CardDojo
function CardProgressionEquipmentExchangeListCell:RefreshCardInfo(cardDojo)
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
    ---@type CardSkinVo
    local cardSkinVo   = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardDojo.cardSkin)
    CfUtils.SetUISwitchImage(self.ImgLine, cardDojo:GetRare())
    CfUtils.SetUISwitchImage(self.ImgFrame, cardDojo:GetRare())
    CfUtils.FillImage(self.ImgHeadIcon, cardSkinVo.buffHead)
    CfUtils.FillText(self.TxtName, cardVo.name)
    CfUtils.FillText(self.TxtName2, cardVo.descr)
end

---刷新卡牌装备
---@param cardDojo CardDojo
function CardProgressionEquipmentExchangeListCell:RefreshCardEquipment(cardDojo)
    for i = 1, CardProgressionConstants.EquipmentNum do
        local key = string.format("equipment%d", i)
        if not self._equipmentList[i] then
            if i == 1 then
                self._equipmentList[i] = self.Node
            else
                local node = self.GoodGroup.gameObject:AddChild(self.Node.gameObject)
                self._equipmentList[i] = node
            end
        end
        self:RefreshEquipGoods(self._equipmentList[i], cardDojo[key], i)
    end
end

---刷新装备道具节点
function CardProgressionEquipmentExchangeListCell:RefreshEquipGoods(node, playEquipId, i)
    local goodsNode = node.transform:Find('GoodNode')
    local emptyNode = node.transform:Find('Empty')

    if checkInt(playEquipId) ~= 0 then
        CfUtils.SetActive(goodsNode, true)
        CfUtils.SetActive(emptyNode, false)
        local equipDojo = equipComp:GetEquipById(playEquipId)
        CfUtils.RefeshGoodGo(goodsNode, equipDojo.equipmentId, nil, 0.5, nil, function () end, playEquipId)
    else
        CfUtils.SetActive(goodsNode, false)
        CfUtils.SetActive(emptyNode, true)
        local icon = emptyNode.transform:Find('ImgIcon')
        CfUtils.SetUISwitchImage(icon, i)
    end
end
